using ReeLib;using System.Text.Json;using System.Collections;
var root="E:/CodexPepo/RE_Research";Directory.SetCurrentDirectory(root);ResourceRepository.LocalResourceRepositoryFolder=root+"/references/reelib-cache";ResourceRepository.DisableOnlineUpdater=true;
var parser=new RszParser(root+"/references/rszre9.json");parser.ReadPatch(root+"/references/rszre9_patch.json");var option=new RszFileOption(GameName.re9,parser);
var jo=new JsonSerializerOptions{WriteIndented=true,IncludeFields=true,NumberHandling=System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals};
object? Value(object? x,int depth=0){if(x is null)return null;if(x is RszInstance i){if(depth>5)return new {Ref=i.Index,Class=i.RszClass.name};var fields=new Dictionary<string,object?>();for(int k=0;k<i.Values.Length;k++)fields[i.Fields[k].name]=Value(i.Values[k],depth+1);return new{Index=i.Index,Class=i.RszClass.name,Userdata=i.RSZUserData?.Path,Fields=fields};}if(x is string||x.GetType().IsPrimitive||x is decimal)return x;if(x is IEnumerable a)return a.Cast<object?>().Select(v=>Value(v,depth+1)).ToArray();return x.ToString();}
var files=JsonDocument.Parse(File.ReadAllText("reports/phase2/effective_files.json")).RootElement;var log=new List<object>();Directory.CreateDirectory("reports/phase2/full");
foreach(var e in files.EnumerateArray()){string path=e.GetProperty("Path").GetString()!,file=e.GetProperty("File").GetString()!;if(!path.Contains(".user.")&&!path.Contains(".motfsm2."))continue;try{using var fh=new FileHandler(file);object data;if(path.Contains(".user.")){using var f=new UserFile(option,fh);if(!f.Read())throw new Exception("Read false");data=new{Path=path,Objects=f.RSZ.ObjectList.Select(x=>Value(x)).ToArray(),Instances=f.RSZ.InstanceList.Select(x=>Value(x,5)).ToArray()};}else{using var f=new Motfsm2File(option,fh);if(!f.Read())throw new Exception("Read false");data=new{Path=path,Nodes=f.BhvtFile.Nodes.Select(n=>new{ID=n.ID.ToString(),n.Name,n.FullName,Parent=n.Parent?.FullName,Actions=n.Actions.Actions.Select(a=>Value(a.Instance)).ToArray(),Selector=Value(n.Selector),Children=n.Children.Children.Select(c=>new{Target=c.ChildNode?.FullName,TargetID=c.ChildNode?.ID.ToString(),Condition=Value(c.Condition)}).ToArray(),EntryTransitions=n.Transitions.Transitions.Select(t=>new{Target=t.StartNode?.FullName,TargetID=t.StartNode?.ID.ToString(),Condition=Value(t.Condition)}).ToArray(),States=n.States.States.Select(s=>new{Target=s.TargetNode?.FullName,TargetID=s.TargetNode?.ID.ToString(),Condition=Value(s.Condition),s.transitionMapID,Transition=s.TransitionData,Events=s.TransitionEvents.Select(x=>Value(x)).ToArray()}).ToArray(),AllStates=n.AllStates.AllStates.Select(s=>new{Target=s.TargetNode?.FullName,TargetID=s.TargetNode?.ID.ToString(),Condition=Value(s.Condition),Transition=s.TransitionData}).ToArray()}).ToArray(),Transitions=f.TransitionDatas};}string dest="reports/phase2/full/"+Path.GetFileName(path)+".json";File.WriteAllText(dest,JsonSerializer.Serialize(data,jo));log.Add(new{Path=path,Success=true});}catch(Exception ex){log.Add(new{Path=path,Success=false,Error=ex.ToString()});Console.WriteLine("FAIL "+Path.GetFileName(path)+": "+ex.Message);}}
File.WriteAllText("reports/phase2/full_parse_log.json",JsonSerializer.Serialize(log,jo));Console.WriteLine("Processed "+log.Count);


foreach(var e in files.EnumerateArray()){string path=e.GetProperty("Path").GetString()!,file=e.GetProperty("File").GetString()!;if(!path.EndsWith("/ch0100_motiontree.motlist.1047"))continue;using var f=new MotlistFile(new FileHandler(file));f.Read();var data=f.Motions.Where(m=>m.MotFile is MotTreeFile).Select(m=>{var t=(MotTreeFile)m.MotFile!;return new{ID=m.motNumber,Switch=m.Switch,t.Name,Nodes=t.Nodes.Select((n,i)=>new{Index=i,n.name,Type=n.TypeInfo?.classShortname,Parameters=n.Parameters.Select(p=>new{p.name,p.type,p.hash,Value=Value(p.value)}).ToArray()}).ToArray(),Links=t.Links.Select(l=>new{l.inputNodeIndex,l.inputPinNo,l.outputNodeIndex,l.outputPinNo,l.type,l.inputGuid,l.outputGuid}).ToArray()};}).ToArray();File.WriteAllText("reports/phase2/full/ch0100_motiontree.typed.json",JsonSerializer.Serialize(data,jo));Console.WriteLine("Typed trees "+data.Length);}

foreach(var e in files.EnumerateArray()){string path=e.GetProperty("Path").GetString()!,file=e.GetProperty("File").GetString()!;if(!path.EndsWith("/playercommonmotionuservariables.uvar.3"))continue;using var f=new UVarFile(new FileHandler(file));f.Read();object Vars(UVarFile v)=>new{Name=v.Header.name,Variables=v.Variables.Select(x=>new{x.Name,x.guid,x.type,Default=Value(x.Value),Expression=x.Expression?.Nodes.Select(n=>new{n.Name,Params=n.Parameters.Select(p=>new{Name=ReeLib.UVar.NodeParameter.GetParameterName(p.nameHash),Value=Value(p.value)}).ToArray()}).ToArray()}).ToArray(),Embedded=v.EmbeddedUVARs.Select(Vars).ToArray()};File.WriteAllText("reports/phase2/full/player_variables.json",JsonSerializer.Serialize(Vars(f),jo));}
